using System;
using System.Globalization;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
namespace LastRail.Run {
 // Matches the supplier's sorted-object JSON.stringify wire contract, including index keys.
 internal static class RunWaveCanonicalJson {
  static bool Index(string s,out uint n)=>uint.TryParse(s,NumberStyles.None,CultureInfo.InvariantCulture,out n)&&n<uint.MaxValue&&n.ToString(CultureInfo.InvariantCulture)==s;
  static string Quote(string value){var b=new StringBuilder("\"");for(int i=0;i<value.Length;i++){char c=value[i];switch(c){case '"':b.Append("\\\"");break;case '\\':b.Append("\\\\");break;case '\b':b.Append("\\b");break;case '\f':b.Append("\\f");break;case '\n':b.Append("\\n");break;case '\r':b.Append("\\r");break;case '\t':b.Append("\\t");break;default:if(c<32||(char.IsSurrogate(c)&&!(char.IsHighSurrogate(c)&&i+1<value.Length&&char.IsLowSurrogate(value[i+1]))&&!(char.IsLowSurrogate(c)&&i>0&&char.IsHighSurrogate(value[i-1]))))b.Append("\\u").Append(((int)c).ToString("x4"));else b.Append(c);break;}}return b.Append('"').ToString();}
  struct Rational {internal System.Numerics.BigInteger N,D;internal Rational(System.Numerics.BigInteger n,System.Numerics.BigInteger d){N=n;D=d;}}
  static Rational Binary(ulong bits){int e=(int)((bits>>52)&2047);ulong mantissa=bits&0xfffffffffffffUL;if(e!=0)mantissa|=1UL<<52;int shift=e==0?-1074:e-1075;return shift>=0?new Rational(new System.Numerics.BigInteger(mantissa)<<shift,1):new Rational(mantissa,System.Numerics.BigInteger.One<<-shift);}
  static Rational Mid(Rational a,Rational b)=>new Rational(a.N*b.D+b.N*a.D,2*a.D*b.D);
  static int Compare(Rational a,Rational b)=>(a.N*b.D).CompareTo(b.N*a.D);
  static Rational Decimal(System.Numerics.BigInteger n,int power)=>power>=0?new Rational(n*System.Numerics.BigInteger.Pow(10,power),1):new Rational(n,System.Numerics.BigInteger.Pow(10,-power));
  internal static double ReadNumber(string literal,double approximate){if(double.IsNaN(approximate)||double.IsInfinity(approximate))throw new ArgumentException("combat_b_wave_number_invalid");bool minus=literal.StartsWith("-",StringComparison.Ordinal);var parts=literal.TrimStart('-').ToLowerInvariant().Split('e');int exp=0;if(parts.Length==2&&!int.TryParse(parts[1],NumberStyles.Integer,CultureInfo.InvariantCulture,out exp)){if(approximate==0)return 0;throw new ArgumentException("combat_b_wave_number_invalid");}if(exp< -400&&approximate==0)return 0;int dot=parts[0].IndexOf('.');int fractional=dot<0?0:parts[0].Length-dot-1;var integer=System.Numerics.BigInteger.Parse(parts[0].Replace(".",""),CultureInfo.InvariantCulture);if(integer.IsZero)return 0;var wanted=Decimal(integer,exp-fractional);ulong bits=(ulong)BitConverter.DoubleToInt64Bits(Math.Abs(approximate));while(true){var center=Binary(bits);var lower=bits==0?new Rational(0,1):Mid(center,Binary(bits-1));var higher=bits==0x7fefffffffffffffUL?Mid(center,new Rational(center.N*2-Binary(bits-1).N,center.D)):Mid(center,Binary(bits+1));bool even=(bits&1)==0;int l=Compare(wanted,lower),h=Compare(wanted,higher);if(l<0||l==0&&!even){bits--;continue;}if(h>0||h==0&&!even){bits++;continue;}return (minus?-1:1)*BitConverter.Int64BitsToDouble((long)bits);}}
  internal static void CorrectParsedNumbers(JObject packet,string json){var literals=new System.Collections.Generic.List<string>();for(int i=0;i<json.Length;i++){if(json[i]=='"'){for(i++;i<json.Length;i++){if(json[i]=='\\'){i++;continue;}if(json[i]=='"')break;}}else if(json[i]=='-'||char.IsDigit(json[i])){int first=i;while(i+1<json.Length&&"0123456789.eE+-".IndexOf(json[i+1])>=0)i++;literals.Add(json.Substring(first,i-first+1));}}var values=packet.Descendants().OfType<JValue>().Where(v=>v.Type==JTokenType.Float||v.Type==JTokenType.Integer).ToArray();if(values.Length!=literals.Count)throw new ArgumentException("combat_b_wave_number_invalid");for(int i=0;i<values.Length;i++)if(values[i].Type==JTokenType.Float)values[i].Value=ReadNumber(literals[i],(double)values[i]);}
  static string Number(JToken token){double n=(double)token;if(double.IsNaN(n)||double.IsInfinity(n))throw new ArgumentException("combat_b_wave_number_invalid");if(n==0)return "0";bool negative=n<0;n=Math.Abs(n);ulong bits=(ulong)BitConverter.DoubleToInt64Bits(n);if(token.Type==JTokenType.Integer){var integer=new Rational(System.Numerics.BigInteger.Abs(System.Numerics.BigInteger.Parse(token.ToString(Formatting.None),CultureInfo.InvariantCulture)),1);while(true){var middle=Binary(bits);int lower=Compare(integer,Mid(middle,Binary(bits-1)));int upper=bits==0x7fefffffffffffffUL?-1:Compare(integer,Mid(middle,Binary(bits+1)));bool even=(bits&1)==0;if(lower<0||lower==0&&!even){bits--;continue;}if(upper>0||upper==0&&!even){bits++;continue;}break;}n=BitConverter.Int64BitsToDouble((long)bits);}var exact=Binary(bits);var low=Mid(exact,Binary(bits-1));var next=bits==0x7fefffffffffffffUL?new Rational(exact.N*2-Binary(bits-1).N,exact.D):Binary(bits+1);var high=Mid(exact,next);bool inclusive=(bits&1)==0;int exponent=(int)Math.Floor(Math.Log10(n));while(Compare(exact,Decimal(1,exponent))<0)exponent--;while(Compare(exact,Decimal(1,exponent+1))>=0)exponent++;System.Numerics.BigInteger chosen=0;int power=0;
   for(int length=1;length<=17;length++){power=exponent-length+1;var scaled=power>=0?new Rational(exact.N,exact.D*System.Numerics.BigInteger.Pow(10,power)):new Rational(exact.N*System.Numerics.BigInteger.Pow(10,-power),exact.D);var rounded=System.Numerics.BigInteger.DivRem(scaled.N,scaled.D,out var remainder);int half=(remainder*2).CompareTo(scaled.D);if(half>0||(half==0&&!rounded.IsEven))rounded++;var candidate=Decimal(rounded,power);int l=Compare(candidate,low),h=Compare(candidate,high);if((l>0||inclusive&&l==0)&&(h<0||inclusive&&h==0)){chosen=rounded;break;}}
   if(chosen.IsZero)throw new ArgumentException("combat_b_wave_number_invalid");string digits=chosen.ToString(CultureInfo.InvariantCulture);int point=digits.Length+power;while(digits.Length>1&&digits.EndsWith("0",StringComparison.Ordinal))digits=digits.Substring(0,digits.Length-1);string result;if(point> -6&&point<=21){result=point<=0?"0."+new string('0',-point)+digits:point>=digits.Length?digits+new string('0',point-digits.Length):digits.Insert(point,".");}else{int e=point-1;result=digits[0]+(digits.Length>1?"."+digits.Substring(1):"")+"e"+(e>=0?"+":"")+e.ToString(CultureInfo.InvariantCulture);}return (negative?"-":"")+result;
  }
  internal static string Canonical(JToken t){if(t is JObject o){var props=o.Properties().Where(p=>p.Name!="__proto__").OrderBy(p=>Index(p.Name,out _)?0:1).ThenBy(p=>Index(p.Name,out var i)?i:0).ThenBy(p=>p.Name,StringComparer.Ordinal);return "{"+string.Join(",",props.Select(p=>Quote(p.Name)+":"+Canonical(p.Value)))+"}";}if(t is JArray a)return "["+string.Join(",",a.Select(Canonical))+"]";if(t.Type==JTokenType.String)return Quote((string)t);if(t.Type==JTokenType.Float||t.Type==JTokenType.Integer)return Number(t);return t.ToString(Formatting.None);}
  internal static string Digest(JToken t){using(var sha=SHA256.Create())return string.Concat(sha.ComputeHash(Encoding.UTF8.GetBytes(Canonical(t))).Select(b=>b.ToString("x2")));}
 }
}
